/* ── GALLERY AUTO-SLIDE (about section) ── */
const images = ["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"];
let idx = 0;
const galleryImg = document.getElementById("gallery-img");
const imgIndexEl = document.getElementById("img-index");
setInterval(() => {
  idx = (idx + 1) % images.length;
  galleryImg.style.opacity = "0";
  setTimeout(() => {
    galleryImg.src = images[idx];
    galleryImg.style.opacity = "1";
    imgIndexEl.textContent = String(idx + 1).padStart(2, "0");
  }, 400);
}, 2000);

/* ── PROJECT GALLERIES ── */
const galleries = { 1:{current:0,auto:null}, 2:{current:0,auto:null}, 3:{current:0,auto:null}, 4:{current:0,auto:null} };
function setSlide(id, index) {
  const items = document.querySelectorAll(`#gallery-${id} img, #gallery-${id} video`);
  const dots  = document.querySelectorAll(`#dots-${id} .dot`);
  items.forEach((el, i) => {
    el.classList.toggle("active", i === index);
    if (el.tagName === "VIDEO") { i === index ? el.play() : (el.pause(), el.currentTime = 0); }
  });
  dots.forEach((d, i) => d.classList.toggle("active", i === index));
  galleries[id].current = index;
}
function startAuto(id) {
  const items = document.querySelectorAll(`#gallery-${id} img, #gallery-${id} video`);
  if (items.length <= 1) return;
  galleries[id].auto = setInterval(() => {
    const next = (galleries[id].current + 1) % items.length;
    setSlide(id, next);
  }, 3000);
}

/* ── PROJECT SCROLL REVEAL ── */
const projectObs = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      e.target.classList.add("visible");
      const id = parseInt(e.target.id.replace("pr",""));
      if (galleries[id] && !galleries[id].auto) startAuto(id);
      projectObs.unobserve(e.target);
    }
  });
}, { threshold: 0.15 });
document.querySelectorAll(".project").forEach(p => projectObs.observe(p));

/* ── REVIEW SCROLL REVEAL ── */
const reviewObs = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      e.target.classList.add("visible");
      reviewObs.unobserve(e.target);
    }
  });
}, { threshold: 0.1 });
document.querySelectorAll(".review-card").forEach(c => reviewObs.observe(c));

/* ── ACHIEVEMENT SCROLL REVEAL ── */
const achObs = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      e.target.classList.add("anim-run");
      achObs.unobserve(e.target);
    }
  });
}, { threshold: 0.08 });
document.querySelectorAll(".ach-card").forEach(c => achObs.observe(c));

/* ── ACHIEVEMENT FILTER ── */
function filterCards(category, btn) {
  document.querySelectorAll(".filter-btn").forEach(b => b.classList.remove("active"));
  btn.classList.add("active");
  document.querySelectorAll(".ach-card").forEach(card => {
    card.style.display = (category === "all" || card.dataset.category === category) ? "" : "none";
  });
  document.querySelectorAll(".year-group").forEach(group => {
    const visible = [...group.querySelectorAll(".ach-card")].some(c => c.style.display !== "none");
    group.style.display = visible ? "" : "none";
  });
}

/* ── STAR RATING ── */
let selectedStars = 0;
document.querySelectorAll(".star-btn").forEach(btn => {
  btn.addEventListener("click", () => {
    selectedStars = parseInt(btn.dataset.star);
    document.querySelectorAll(".star-btn").forEach((b, i) => {
      b.classList.toggle("lit", i < selectedStars);
    });
  });
  btn.addEventListener("mouseenter", () => {
    const hover = parseInt(btn.dataset.star);
    document.querySelectorAll(".star-btn").forEach((b, i) => {
      b.classList.toggle("lit", i < hover);
    });
  });
  btn.addEventListener("mouseleave", () => {
    document.querySelectorAll(".star-btn").forEach((b, i) => {
      b.classList.toggle("lit", i < selectedStars);
    });
  });
});

/* ── FEEDBACK SUBMIT ── */
document.getElementById("submitFb").addEventListener("click", () => {
  const name = document.getElementById("fb-name").value.trim();
  const msg  = document.getElementById("fb-msg").value.trim();
  if (!name || !msg) {
    document.getElementById("fb-name").style.borderColor = name ? "rgba(57,255,20,0.2)" : "#ff4444";
    document.getElementById("fb-msg").style.borderColor  = msg  ? "rgba(57,255,20,0.2)" : "#ff4444";
    return;
  }
  document.getElementById("feedbackForm").style.opacity = "0.4";
  document.getElementById("feedbackForm").style.pointerEvents = "none";
  document.getElementById("successMsg").classList.add("show");
  setTimeout(() => {
    document.getElementById("feedbackForm").style.opacity = "1";
    document.getElementById("feedbackForm").style.pointerEvents = "";
    document.getElementById("successMsg").classList.remove("show");
    document.getElementById("fb-name").value = "";
    document.getElementById("fb-role").value = "";
    document.getElementById("fb-email").value = "";
    document.getElementById("fb-msg").value = "";
    document.getElementById("fb-category").value = "";
    selectedStars = 0;
    document.querySelectorAll(".star-btn").forEach(b => b.classList.remove("lit"));
  }, 3500);
});


/* ── CERTIFICATES LIGHTBOX ── */
function openLightbox(type, src) {
  const lb = document.getElementById("cert-lightbox");
  const img = document.getElementById("cert-lb-img");
  const ifr = document.getElementById("cert-lb-iframe");
  if (type === 'img') {
    img.src = src; img.style.display = "block";
    ifr.src = ""; ifr.style.display = "none";
  } else {
    const el = document.getElementById(src);
    ifr.src = el ? el.src : src; ifr.style.display = "block";
    img.src = ""; img.style.display = "none";
  }
  lb.classList.add("open");
  document.body.style.overflow = "hidden";
}
function closeLightbox() {
  document.getElementById("cert-lightbox").classList.remove("open");
  document.getElementById("cert-lb-img").src = "";
  document.getElementById("cert-lb-iframe").src = "";
  document.body.style.overflow = "";
}
document.addEventListener("keydown", e => { if(e.key==="Escape") closeLightbox(); });

